def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    honey_bottle_patches = image_patch.find("honey bottle")
    if not honey_bottle_patches: 
        return image_patch

    honey_bottles_on_left = [hb for hb in honey_bottle_patches if hb.horizontal_center < image_patch.width / 2]

    if not honey_bottles_on_left: 
        return image_patch

    honey_bottle_without_face = [hb for hb in honey_bottles_on_left if not hb.exists("face")]

    return honey_bottle_without_face[0] if honey_bottle_without_face else honey_bottles_on_left[0]

